CREATE TABLE IF NOT EXISTS p11_arena_members (player_id BIGINT PRIMARY KEY,position BIGINT NOT NULL,active BOOLEAN NOT NULL,info LONGBLOB NOT NULL,battle LONGBLOB NOT NULL,snapshot_hash VARCHAR(64) NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,best_won_rank BIGINT NOT NULL,UNIQUE KEY idx_p11_arena_position(position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
